import{_ as t,c as e,o,ae as i}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"Default Data Filtering Shortcode","description":"Default Data Filtering Shortcode","frontmatter":{"title":"Default Data Filtering Shortcode","description":"Default Data Filtering Shortcode"},"headers":[],"relativePath":"guide/advanced-features/default-data-filtering-shortcode.md","filePath":"guide/advanced-features/default-data-filtering-shortcode.md"}'),s={name:"guide/advanced-features/default-data-filtering-shortcode.md"};function n(r,a,l,d,h,c){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="default-data-filtering-shortcode" tabindex="-1">Default Data Filtering Shortcode <a class="header-anchor" href="#default-data-filtering-shortcode" aria-label="Permalink to &quot;Default Data Filtering Shortcode&quot;">​</a></h1><p>Default Data Filtering Shortcode feature allows you to quickly and easily display just the rows you want to show by providing a simple filter text in the table shortcode. In this case, you should filter the data created earlier in the table. Default Data Filtering Shortcode is a Pro Feature! For instance, say you have a table with lots of movie data, and you want to show the rows that only contain Adventure. This can be previously done in only one possible way- your user had to search for <strong>Adventure</strong> movies manually, given that you have allowed the**<a href="https://ninjatables.com/docs/add-or-remove-search-or-filter-functionality/" target="_blank" rel="noreferrer"> Search / Filter </a>**options in your table. However, the <strong>Default Data Filtering</strong> feature allows you as an admin to set default filtering options in a table containing a huge amount of data.</p><h2 id="data-filtering-shortcode-usage" tabindex="-1">Data Filtering Shortcode Usage <a class="header-anchor" href="#data-filtering-shortcode-usage" aria-label="Permalink to &quot;Data Filtering Shortcode Usage&quot;">​</a></h2><p>Regarding this, we also included more practical features. Please double-check the usage.</p><h3 id="simple" tabindex="-1">Simple <a class="header-anchor" href="#simple" aria-label="Permalink to &quot;Simple&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&quot;TABLEID&quot; filter=&quot;john smith&quot;]</span></span></code></pre></div><p>This will show the rows which contain <strong>john</strong> <strong>smith</strong>.</p><h3 id="and" tabindex="-1">AND <a class="header-anchor" href="#and" aria-label="Permalink to &quot;AND&quot;">​</a></h3><p>Make a query more specific by separating additional parts with a capitalized <em><strong>AND</strong></em> string.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&quot;TABLEID&quot; filter=&quot;john AND smith&quot;]</span></span></code></pre></div><p>This would match all rows containing both <strong>john</strong> <strong>AND</strong> <strong>smith</strong>.</p><h3 id="or" tabindex="-1">OR <a class="header-anchor" href="#or" aria-label="Permalink to &quot;OR&quot;">​</a></h3><p>Expand a query by separating additional parts with a capitalized <em><strong>OR</strong></em> string.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&quot;TABLEID&quot; filter=&quot;john OR smith&quot;]</span></span></code></pre></div><p>This would match all rows containing both <strong>john OR smith</strong>.</p><h3 id="negate" tabindex="-1">Negate <a class="header-anchor" href="#negate" aria-label="Permalink to &quot;Negate&quot;">​</a></h3><p>Exclude a value from the results by prefixing it with a minus <em><strong>-</strong></em> sign.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&quot;TABLEID&quot; filter=&quot;john -smith&quot;]</span></span></code></pre></div><p>This would match all rows containing the word <strong>john</strong> but would exclude any containing <strong>smith</strong>.</p><p>Make a query more specific by separating additional parts with a capitalized <em><strong>AND</strong></em> string.</p><h3 id="phrases" tabindex="-1">Phrases <a class="header-anchor" href="#phrases" aria-label="Permalink to &quot;Phrases&quot;">​</a></h3><p>Match an exact word or phrase by wrapping it in quotes (&quot; &quot;).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&quot;TABLEID&quot; filter=&#39;&quot;brown fox&quot;&#39;]</span></span></code></pre></div><p>The above query would match all rows containing the exact phrase <strong>brown fox</strong>.</p><p>You can quickly use your site&#39;s standard data filtering shortcode by reading this article!</p>',25)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
